"""Bounded retrospective measurement of one already installed B0 reverse segment."""
from pathlib import Path
import json,numpy as np,hashlib
H=Path(__file__).resolve().parent;B=H/'native_pose_baseline35_e1_coverage_run_v1';D=H/'B0_initial_backing_execution_audit_v1'
def main():
 D.mkdir(exist_ok=False);rows=json.loads((B/'policy_records.json').read_text());states=json.loads((B/'states.json').read_text());physics=np.load(B/'physics.npz');a=next(r for r in rows if r.get('local_reference_version')==2);i=a['frame'];plan=json.loads((B/'local_plans'/f'frame_{i:03d}.json').read_text());w=plan['waypoints'];j=next(j for j,x in enumerate(w[:-1]) if x['drive_direction']!='reverse');ref=np.array([[x['x_m'],x['y_m']] for x in w[:j+1]]);assert j==5
 phase=[r for r in rows[i:] if r['local_reference_version']==2];last=phase[-1]['frame'];indices=np.arange(i,min(last+2,len(states)));xy=np.array([states[k]['position'][:2] for k in indices]);delta=np.diff(ref,axis=0);length=np.linalg.norm(delta,axis=1);arc=np.r_[0,np.cumsum(length)];u=np.clip(((xy[:,None]-ref[:-1])*delta).sum(2)/length**2,0,1);proj=ref[:-1]+u[:,:,None]*delta;dist=np.linalg.norm(xy[:,None]-proj,axis=2);best=dist.argmin(1);progress=arc[best]+u[np.arange(len(xy)),best]*length[best];enddist=np.linalg.norm(xy-ref[-1],axis=1)
 main_col=12;native=json.loads((B/'native_predictions.json').read_text());reverse_rows=[r for r in phase if r['tracker_state_after_act']['active_direction']=='reverse'];pending=[r for r in phase if r['tracker_state_after_act']['pending_direction']=='reverse'];feedback=[(r['time_s'],float(native[r['frame']*5]['proprio_history'][-1][main_col])) for r in phase] if native and 'proprio_history' in native[0] else []
 # Actual articulated measurement is authoritative; do not infer it from cursor or request.
 mask=(physics['simulation_time_s']>=states[i]['time_s']-1e-5)&(physics['simulation_time_s']<=states[indices[-1]]['time_s']+1e-5);vel=physics['joint_velocity_rad_s'][mask,0];times=physics['simulation_time_s'][mask];negative=np.flatnonzero(vel<-.1)
 r=dict(scope='one historical B0 reference2 only; offline not new online validation',reference_version=2,first_installed_frame=i,first_installed_time_s=a['time_s'],last_sample_s=states[indices[-1]]['time_s'],nominal_initial_reverse_edges=j,nominal_reverse_arc_m=float(length.sum()),first_actual_latched_reverse_time_s=None if not reverse_rows else reverse_rows[0]['time_s'],first_joint1_velocity_below_minus_0p1_s=None if not len(negative) else float(times[negative[0]]),pending_reverse_rows=len(pending),max_true_projected_reverse_arc_m=float(progress.max()),closest_true_first_cusp_m=float(enddist.min()),first_cusp_within_original_0p2_m=bool(np.any(enddist<=.2)),cross_RMS_to_first_reverse_polyline_m=float(np.sqrt(np.mean(dist[np.arange(len(xy)),best]**2))),no_cursor_used_for_geometry=True,no_controller_change=True,no_new_physics=True,not_short_backing_candidate_assessment=True)
 (D/'assessment.json').write_text(json.dumps(r,indent=2)+'\n');(D/'inputs.json').write_text(json.dumps({str(p):hashlib.sha256(p.read_bytes()).hexdigest() for p in [B/'policy_records.json',B/'states.json',B/'physics.npz',B/'local_plans'/f'frame_{i:03d}.json']},indent=2)+'\n');print(json.dumps(r,indent=2))
